    /**
     * @throws JsonException
     */
    public function testRunReportsFixabilityReasonsAndDiffsWithoutWritingDuringPreview(): void
    {
        $project = new \Tests\Support\Project([
            'app.json' => '{"workers":0}',
            'guard.yaml' => "version: 1\nconfiguration:\n  - {id: workers, file: app.json, select: /workers, reason: Bound concurrency, assert: {equals: 2}}\n  - {id: missing, file: absent.json, select: /x, assert: {equals: 1}}\n",
        ]);
        $output = '';
        $application = new \Guard\Cli\Application($project->root, static function (string $text) use (&$output): void {
            $output .= $text;
        });
        try {
            self::assertSame(1, $application->run(['check', '--format=json', '--ansi']));
            $check = json_decode($output, true, 512, JSON_THROW_ON_ERROR);
            self::assertTrue($check['findings'][0]['fixable']);
            self::assertFalse($check['findings'][1]['fixable']);
            self::assertSame('Bound concurrency', $check['findings'][0]['reason']);
            self::assertSame('checked', $check['action']);
            $output = '';
            self::assertSame(1, $application->run(['fix', '--dry-run', '--format=json']));
            $preview = json_decode($output, true, 512, JSON_THROW_ON_ERROR);
            self::assertSame('blocked', $preview['action']);
            self::assertStringContainsString('-{"workers":0}', $preview['diffs'][0]['diff']);
            self::assertStringContainsString('+    "workers": 2', $preview['diffs'][0]['diff']);
            self::assertSame('{"workers":0}', file_get_contents($project->root . '/app.json'));
            self::assertSame(1, $application->run(['fix', '--format=text']));
            self::assertSame('{"workers":0}', file_get_contents($project->root . '/app.json'));
            self::assertSame(2, $application->run(['apply']));
        } finally {
            $project->remove();
        }
    }

    public function testRunExplicitHumanFormatOverridesAgentDetection(): void
    {
        $project = new \Tests\Support\Project(['guard.yaml' => "version: 1\n"]);
        $before = getenv('AI_AGENT');
        $output = '';
        $application = new \Guard\Cli\Application($project->root, static function (string $text) use (&$output): void {
            $output .= $text;
        });
        try {
            putenv('AI_AGENT=test');
            self::assertSame(0, $application->run(['check']));
            self::assertStringNotContainsString('Guard check', $output);
            $output = '';
            self::assertSame(0, $application->run(['check', '--format=human', '--ansi']));
            self::assertStringContainsString('Guard check', $output);
            self::assertStringContainsString("\033[", $output);
            $output = '';
            self::assertSame(0, $application->run(['check', '--format=human', '--no-ansi']));
            self::assertStringNotContainsString("\033", $output);
        } finally {
            putenv($before === false ? 'AI_AGENT' : 'AI_AGENT=' . $before);
            $project->remove();
        }
    }
