            foreach ($policy->limits->values() as $metric => $limit) {
                if ($limit === null) {
                    continue;
                }
                $id = 'metrics.' . str_replace('.', '_', $metric);
                $rules[] = new RuleDescription(
                    $id,
                    implode(', ', $config->scan->roots),
                    'required',
                    false,
                    (new RuleReasons())->forRule($id),
                    ['profile' => $profile, 'max' => $limit, 'source' => $config->scan->roots, 'exclude' => $config->scan->exclude,
