final class RuleReasons
{
    /**
     * Returns a rationale without pretending a custom rule supplied one.
     */
    public function forRule(string $id): string
    {
        if (str_starts_with($id, 'metrics.')) {
            return str_contains($id, 'complexity')
                ? 'Limit independent execution paths so the code can be understood and tested with a manageable number of cases.'
                : 'Keep each source unit small enough to review and change without mixing unrelated responsibilities.';
        }
        if (str_starts_with($id, 'structure.')) {
            return 'Keep files in predictable locations and constrain directory growth so contributors can find the correct place for a change.';
        }
        if (str_starts_with($id, 'documentation.')) {
            return 'Preserve the agreed document structure and content so readers can find information and generated edits do not silently change the documentation contract.';
        }
        return 'No reason provided. Add a reason to this rule in guard.yaml.';
    }
}
