        if (isset($examples[$id])) {
            $message = $label . ' {select} in {file} must {expectation}. ' . $examples[$id];
        }
        if (str_starts_with($id, 'composer.describe-')) {
            $message = 'The script description at {select} in {file} must {expectation}. Add a scripts-descriptions entry explaining what the corresponding Composer command checks or generates.';
